class Solution {
    public long maxBalancedSubsequenceSum(int[] nums){
        int n=nums.length;
        long[] keys=new long[n],sorted=new long[n];
        for(int i=0;i<n;i++)keys[i]=sorted[i]=(long)nums[i]-i;
        Arrays.sort(sorted);
        int unique=0;
        for(long key:sorted)if(unique==0||sorted[unique-1]!=key)sorted[unique++]=key;
        long[] tree=new long[unique+1];
        long answer=Long.MIN_VALUE;
        for(int i=0;i<n;i++){
            int rank=Arrays.binarySearch(sorted,0,unique,keys[i])+1;
            long best=0;
            for(int x=rank;x>0;x-=x&-x)best=Math.max(best,tree[x]);
            long current=nums[i]+best;
            answer=Math.max(answer,current);
            for(int x=rank;x<=unique;x+=x&-x)tree[x]=Math.max(tree[x],current);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxBalancedSubsequenceSum(nums:IntArray):Long{
        val n=nums.size;
        val keys=LongArray(n){
            nums[it].toLong()-it
        };
        val sorted=keys.sorted().distinct();
        val tree=LongArray(sorted.size+1);
        var answer=Long.MIN_VALUE;
        for(i in nums.indices){
            val rank=sorted.binarySearch(keys[i])+1;
            var best=0L;
            var x=rank;
            while(x>0){
                best=maxOf(best,tree[x]);
                x-=x and -x
            };
            val current=nums[i]+best;
            answer=maxOf(answer,current);
            x=rank;
            while(x<tree.size){
                tree[x]=maxOf(tree[x],current);
                x+=x and -x
            }
        };
        return answer
    }
}

